CREATE TABLE IF NOT EXISTS world_monster_loot (prototype INTEGER PRIMARY KEY, coins INTEGER NOT NULL, drop_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS world_drop_rules (drop_id INTEGER NOT NULL, slot INTEGER NOT NULL, item INTEGER NOT NULL, chance INTEGER NOT NULL, PRIMARY KEY(drop_id,slot));
CREATE TABLE IF NOT EXISTS world_drop_groups (group_id INTEGER NOT NULL, slot INTEGER NOT NULL, item INTEGER NOT NULL, PRIMARY KEY(group_id,slot));
CREATE TABLE IF NOT EXISTS account_storage (account TEXT NOT NULL COLLATE NOCASE, position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 191), item_id INTEGER NOT NULL, durability INTEGER NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(account,position));
CREATE TABLE IF NOT EXISTS account_bank (account TEXT PRIMARY KEY COLLATE NOCASE, coins INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS world_reference_rules (table_name TEXT NOT NULL, rule_id INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(table_name,rule_id));
CREATE TABLE IF NOT EXISTS world_upgrade_item_types (item_id INTEGER PRIMARY KEY, item_class INTEGER NOT NULL, item_ext INTEGER NOT NULL);
